package app.overman.sleep;
public final class AlarmDeliveryPolicyCheck {
 static int checks;static void expect(boolean value,long planned,long received,long now,boolean ringing){if(AlarmDeliveryPolicy.accept(planned,received,now,ringing)!=value)throw new AssertionError("Unexpected delivery decision");checks++;}
 static void resume(boolean expected,long planned,long received,long now,boolean ringing,long wokeAt,String delivery,String session){if(AlarmDeliveryPolicy.resume(planned,received,now,ringing,wokeAt,delivery,session)!=expected)throw new AssertionError("Unexpected resume decision");checks++;}
 public static void main(String[] args){expect(true,10000,10000,10000,false);expect(true,10000,10000,70000,false);expect(false,10000,10000,10000,true);expect(false,20000,10000,20000,false);expect(false,20000,20000,10000,false);expect(false,0,0,10000,false);expect(false,-1,-1,10000,false);expect(true,10000,10000,9000,false);expect(false,10000,10000,8999,false);resume(true,10000,10000,10000,true,0,"night","night");resume(false,10000,10000,10000,false,0,"night","night");resume(false,10000,10000,10000,true,1,"night","night");resume(false,10000,10000,10000,true,0,"old","night");resume(false,10000,10000,10000,true,0,null,"night");resume(false,10000,10000,10000,true,0,"","");resume(false,20000,10000,20000,true,0,"night","night");resume(false,20000,20000,10000,true,0,"night","night");resume(false,0,0,10000,true,0,"night","night");System.out.println(checks+" delivery policy cases passed");}
}
